contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will test that when called from this contract (which is NOT the original owner of c),
    // attempts to withdraw or sendMoney revert and leave depositsCount and c's balance unchanged.
    function run(uint sendAmount, uint callValue) public payable {
        require(address(this).balance >= callValue, "Insufficient balance for callValue");
        // Read before-values
        uint beforeDeposits = c.depositsCount();
        uint beforeBalance = address(c).balance;

        // Try withdrawAll and capture revert
        bool withdrewAllReverted;
        try c.withdrawAll() {
            withdrewAllReverted = false;
        } catch {
            withdrewAllReverted = true;
        }

        // Try withdraw(sendAmount) and capture revert
        bool withdrawReverted;
        try c.withdraw(sendAmount) {
            withdrawReverted = false;
        } catch {
            withdrawReverted = true;
        }

        // Try sendMoney to some address (use address(this)) and send along callValue ETH
        bool sendMoneyReverted;
        // ensure the call that sends ETH has the funds in this contract
        if (callValue > 0) {
            // call c.sendMoney with value
            try c.sendMoney{value: callValue}(address(this), sendAmount) {
                sendMoneyReverted = false;
            } catch {
                sendMoneyReverted = true;
            }
        } else {
            try c.sendMoney(address(this), sendAmount) {
                sendMoneyReverted = false;
            } catch {
                sendMoneyReverted = true;
            }
        }

        // Read after-values
        uint afterDeposits = c.depositsCount();
        uint afterBalance = address(c).balance;

        // General rule: since this contract is NOT the owner of c, all three privileged calls must revert,
        // and if they revert the contract's depositsCount and balance must remain unchanged.
        // (We assert that either all revert and state unchanged, or if any did not revert then at least one of
        // the state observables changed accordingly — but we prefer the strict rule that non-owner cannot
        // successfully perform them, so assert they all reverted and no state change occurred.)
        assert(withdrewAllReverted && withdrawReverted && sendMoneyReverted &&
               beforeDeposits == afterDeposits && beforeBalance == afterBalance);
    }

    // Accept ETH forwarded to this test contract when c.sendMoney calls back
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // This test tries privileged calls from a non-owner caller (this contract).
    // It asserts that these calls revert and that depositsCount and c's balance remain unchanged.
    function run(uint sendAmount, uint callValue) public payable {
        // ensure this contract has enough balance if we intend to provide value to c.sendMoney
        require(address(this).balance >= callValue, "insufficient balance for callValue");

        // observe before state
        uint beforeDeposits = c.depositsCount();
        uint beforeBalance = address(c).balance;

        // try withdrawAll
        bool withdrewAllReverted;
        try c.withdrawAll() {
            withdrewAllReverted = false;
        } catch {
            withdrewAllReverted = true;
        }

        // try withdraw(sendAmount)
        bool withdrawReverted;
        try c.withdraw(sendAmount) {
            withdrawReverted = false;
        } catch {
            withdrawReverted = true;
        }

        // try sendMoney to this contract; if callValue>0 we must send it as value to c (c.call internal may forward it)
        bool sendMoneyReverted;
        if (callValue > 0) {
            // fund c by sending ETH to c first so that calling sendMoney does not require c to hold that ETH
            // send Ether to c via low-level call to trigger fallback and increase depositsCount
            (bool sent,) = address(c).call{value: callValue}("");
            // the low-level call to c's fallback may succeed or fail depending on callValue, but we proceed regardless
            // now attempt privileged sendMoney which should revert for non-owner
            try c.sendMoney(address(this), sendAmount) {
                sendMoneyReverted = false;
            } catch {
                sendMoneyReverted = true;
            }
        } else {
            try c.sendMoney(address(this), sendAmount) {
                sendMoneyReverted = false;
            } catch {
                sendMoneyReverted = true;
            }
        }

        // observe after state
        uint afterDeposits = c.depositsCount();
        uint afterBalance = address(c).balance;

        // General rule: because this contract is not the owner of c, all three privileged calls must revert
        // and c's depositsCount and balance must remain unchanged by those failed attempts.
        assert(withdrewAllReverted && withdrawReverted && sendMoneyReverted &&
               beforeDeposits == afterDeposits && beforeBalance == afterBalance);
    }

    // accept ETH when c sends back to this test contract
    receive() external payable {}
}

