        // Optionally fund c by sending Ether to trigger fallback (this is a state-changing call on c)
        if (fundAmount > 0) {
            // top-level state-changing call to c
            (bool okFund, ) = address(c).call{value: fundAmount}("");
            // we do not require okFund; fallback may revert on gas, but funding attempt is part of setup
