contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Run a single scenario: attempt withdraw and withdrawAll from this contract (not owner)
    // We require that if calls revert then balances remain unchanged; if they don't revert then caller must be owner.
    function run(uint sendAmount) public payable {
        require(address(this).balance >= sendAmount);

        // Fund contract C by sending Ether to its fallback via this test contract calling with value.
        // The fallback increments depositsCount; we observe depositsCount and balances.
        uint beforeCBalance = address(c).balance;
        uint beforeThisBalance = address(this).balance;
        uint beforeDeposits = c.depositsCount();

        // send money into C to increase its balance
        c.sendMoney{value: 0}(address(c), 0); // no-op to ensure call structure present (safe)
        // Actually transfer Ether to C by calling fallback: use .call on c address from this contract
        (bool okFund,) = address(c).call{value: sendAmount}("");
        // okFund may be true normally; require nothing about it

        uint afterFundCBalance = address(c).balance;
        uint afterFundThisBalance = address(this).balance;
        uint afterDeposits = c.depositsCount();

        // Now attempt withdraw and withdrawAll from this contract (InvMutTest) which is NOT the owner of C
        bool withdrewReverted;
        try c.withdrawAll() {
            withdrewReverted = false;
        } catch {
            withdrewReverted = true;
        }

        bool withdrawReverted;
        try c.withdraw(1) {
            withdrawReverted = false;
        } catch {
            withdrawReverted = true;
        }

        // After these attempts, balances should only change if the calls did not revert and caller is owner.
        // Since this contract is not the original deployer (owner) of C, both calls must revert.
        // General rule: if caller is not owner, withdraw/withdrawAll revert and do not change balances or depositsCount.
        // We can observe owner via public getter to state the rule conditionally.
        address owner = c.owner();

        // Assert the invariant: if this contract is not the owner, then both withdraw calls reverted and C's balance and this balance and depositsCount unchanged from after funding.
        assert( (address(this) == owner) || (
            withdrewReverted && withdrawReverted
            && address(c).balance == afterFundCBalance
            && address(this).balance == afterFundThisBalance
            && c.depositsCount() == afterDeposits
        ) );
    }

    // accept Ether so funding works
    receive() external payable {}
}

