contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // This test takes parameters to drive behavior: amount to fund C, amount to send via sendMoney, and a target address.
    // It asserts a general invariant: if sendMoney call succeeds (does not revert) then
    //  - C.balance after the call is <= C.balance before the call and >= C.balance before minus the requested _value,
    //  - depositsCount is unchanged by the sendMoney call.
    function run(uint fundAmount, uint sendAmount, address payable target) public payable {
        require(true);

        // Ensure this contract has enough ETH to fund C if requested
        if (fundAmount > 0) {
            require(address(this).balance >= fundAmount);
            // fund C by triggering fallback which increments depositsCount
            // fallback increments depositsCount on any plain ether transfer
            (bool okFund,) = address(c).call{value: fundAmount}("");
            // funding could in theory fail, but we still proceed; if it failed, C state unchanged
        }

        // Read before-values
        uint beforeBalance = address(c).balance;
        uint beforeDeposits = c.depositsCount();

        // Attempt sendMoney; capture whether it reverted
        bool reverted;
        try c.sendMoney(target, sendAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after-values
        uint afterBalance = address(c).balance;
        uint afterDeposits = c.depositsCount();

        // If sendMoney succeeded then:
        //  - depositsCount must be unchanged (sendMoney should not trigger fallback on C itself)
        //  - afterBalance cannot have increased; and cannot have decreased by more than sendAmount
        // If sendMoney reverted then no guarantees are required here (other than this assert can still reference reverted).
        assert( reverted || (afterDeposits == beforeDeposits && afterBalance <= beforeBalance && afterBalance + sendAmount >= beforeBalance) );
    }

    // Allow receiving ETH so the test contract can fund C
    receive() external payable {}
}

