contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will attempt to call sendMoney and observe effects. We take target and amount as inputs.
    // The contract may need to send Ether to c before testing, so we accept an upfront funding amount
    // and require this contract has enough balance to fund c.
    function run(address payable target, uint amountToSendToTarget, uint fundAmount) public payable {
        require(address(this).balance >= fundAmount, "insufficient test balance");

        // Fund C by invoking its fallback: send Ether to C so its balance increases and depositsCount increments.
        // Call fallback by sending value to c address. This is a top-level state-changing call on c.
        // Use low-level call on c to trigger fallback payable (the contract C has fallback payable).
        (bool funded,) = address(c).call{value: fundAmount}("");
        // funded may be true/false; but fallback in C is payable so expected true. We don't require here.

        // Read observable state before sendMoney attempt
        uint beforeBalance = address(c).balance;
        uint beforeDeposits = c.depositsCount();

        // Attempt to call sendMoney; capture whether it reverts.
        bool reverted;
        try c.sendMoney(target, amountToSendToTarget) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read observable state after call
        uint afterBalance = address(c).balance;
        uint afterDeposits = c.depositsCount();

        // General rule asserted:
        // If sendMoney did NOT revert, then C.balance decreased by exactly amountToSendToTarget
        // and depositsCount did not change (fallback shouldn't be triggered by sendMoney).
        assert(reverted || (beforeBalance >= amountToSendToTarget && afterBalance + amountToSendToTarget == beforeBalance && afterDeposits == beforeDeposits));
    }

    // Allow receiving Ether so the test can be funded externally
    receive() external payable {}
}

