contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // The test drives c.sendMoney with arbitrary target and amount, after optionally funding c via its fallback.
    // We assert that if sendMoney does not revert then total Ether between c and this contract is unchanged
    // (i.e., sendMoney cannot create or destroy Ether), and if it reverts then no Ether was transferred from c to this contract.
    function run(address target, uint amount, uint fundAmount) public payable {
        require(address(this).balance >= fundAmount, "insufficient balance to fund");

        // Record initial balances
        uint beforeC = address(c).balance;
        uint beforeThis = address(this).balance;

        // Optionally fund contract c by calling its fallback via a plain call to c with value
        if (fundAmount > 0) {
            // ensure we have the funds in this contract
            // call fallback: this is a direct low-level call which will trigger C.fallback and increment depositsCount
            (bool okFund, ) = address(c).call{value: fundAmount}("");
            // funding could in theory fail; require it succeeded so totals are meaningful
            require(okFund, "funding failed");
        }

        // Read balances after funding
        uint midC = address(c).balance;
        uint midThis = address(this).balance;

        bool reverted;
        // Attempt to call sendMoney from this contract (this contract is the owner of c)
        try c.sendMoney(target, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterC = address(c).balance;
        uint afterThis = address(this).balance;

        // General rule:
        // - If sendMoney returned (did not revert), then total Ether between c and this contract is unchanged:
        //   afterC + afterThis == midC + midThis
        // - If sendMoney reverted, then balances remain exactly as before the call:
        //   afterC == midC && afterThis == midThis
        assert((!reverted && (afterC + afterThis == midC + midThis)) || (reverted && afterC == midC && afterThis == midThis));
    }

    // Allow receiving Ether when external calls target this contract
    receive() external payable {}
}

