        uint beforeDeposits = c.depositsCount();

        // We only test behavior for amounts that are <= current contract balance to avoid intrinsic transfer failure
        if (withdrawAmount > beforeBalance) {
            // In this case we expect withdraw (when owner) still may be called with larger value,

            // but withdraw uses transfer which will revert if insufficient funds; to exercise the general rule
            // about successful owner withdraws we skip calling when amount > balance so the assert remains general.
            // Make a harmless call to not change state: call sendMoney with zero value (will not increase balance)
            c.sendMoney(address(this), 0);

