            uint afterBalance = address(c).balance;
            uint afterDeposits = c.depositsCount();

            // General rule still must hold: since no successful withdraw attempted, balance didn't increase and depositsCount didn't increase from this call
            assert(afterBalance >= 0 && afterBalance == beforeBalance && afterDeposits == beforeDeposits);
            return;
        }

        bool reverted;
        if (useWithdrawAll) {
            // Try withdrawAll as owner (this contract is owner). Capture revert.
            try c.withdrawAll() {
                reverted = false;
            } catch {
                reverted = true;
            }
