contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We use parameters to send a low-level .call that triggers fallback on c.
    function run(address target, uint amount) public payable {
        require(address(this).balance >= amount);
        // record before values
        uint beforeCount = c.depositsCount();
        uint beforeBal = address(c).balance;

        bool ok;
        // perform low-level call to trigger fallback on c
        (ok, ) = address(c).call{value: amount}("");

        uint afterCount = c.depositsCount();
        uint afterBal = address(c).balance;

        // General rule: if the call reverted (ok == false) then depositsCount and balance unchanged;
        // otherwise depositsCount increased by exactly 1 and balance increased by exactly amount.
        assert(
            (ok == false && afterCount == beforeCount && afterBal == beforeBal) ||
            (ok == true && afterCount == beforeCount + 1 && afterBal == beforeBal + amount)
        );
    }

    receive() external payable {}
}
